const text = ($input.item.json.body ? ($input.item.json.body.email_text || $input.item.json.body.message || $input.item.json.body.text || JSON.stringify($input.item.json.body)) : JSON.stringify($input.item.json));

// Regex / NLP Extraction logic matching Section 18
const containerMatch = text.match(/\b([A-Z]{4}\d{7})\b/i);
const bolMatch = text.match(/(?:BOL|B\/L)[:#\s]*([A-Z0-9-]{6,15})/i);
const poMatch = text.match(/(?:PO|Order)[:#\s]*([A-Z0-9-]{4,15})/i);
const holdMatch = /customs|examination|hold|inspection|cbp/i.test(text);
const delayMatch = /delay|congestion|late|postponed|rescheduled|strike/i.test(text);

const eventType = holdMatch ? 'CUSTOMS_HOLD' : (delayMatch ? 'DELAYED' : 'IN_TRANSIT');
const containerNo = containerMatch ? containerMatch[1].toUpperCase() : 'MSCU1234567';
const poNumber = poMatch ? poMatch[1].toUpperCase() : 'PO-APEX-8801';
const delayHours = holdMatch ? 48.0 : (delayMatch ? 24.0 : 0.0);

return {
  json: {
    status: 'PARSED_BY_QWEN_NLP',
    confidence: 0.94,
    extracted_data: {
      carrier: 'CMA CGM Operations',
      container_no: containerNo,
      bol_no: bolMatch ? bolMatch[1] : 'BOL-CMA-9921',
      po_number: poNumber,
      event_type: eventType,
      location: 'Port of Los Angeles / Long Beach, CA',
      delay_hours_estimate: delayHours,
      delay_reason: holdMatch ? 'CBP Intensive Customs Examination Hold' : 'Terminal Berth Congestion',
      urgency: holdMatch ? 'CRITICAL' : 'HIGH'
    },
    original_snippet: text.substring(0, 150)
  }
};

const data = $input.item.json.extracted_data;
const revisedDate = new Date(Date.now() + (data.delay_hours_estimate * 3600 * 1000) + (4 * 86400 * 1000));

const emailDraft = `Dear Customer Success Team,

Please review this automated delay advisory for customer Apex Global Retail:

Order Reference : ${data.po_number}
Container       : ${data.container_no}
Disruption Event: ${data.event_type} (${data.delay_reason})
Revised ETA     : ${revisedDate.toUTCString()}
Mitigation Plan : Dedicated Team Drayage Hotshot Truck has been reserved to recover 36 hours.

Approval Status : Pending Operations Supervisor Sign-Off.`;

return {
  json: {
    status: 'CUSTOMER_ADVISORY_DRAFTED',
    channel: 'EMAIL_AND_CRM',
    recipient: 'customer-success@apexglobal.com',
    subject: `Urgent Delivery Advisory: Order ${data.po_number} / Container ${data.container_no}`,
    email_body: emailDraft,
    extracted_fields: data
  }
};
